missions.solution:
public class Countdown {
    public static void main(String[] args) {
        for (int i = 5; i > 0; i--) {
            System.out.println("Noch " + i);
            robot.move();
            if (robot.onCoin()) {
                robot.pickCoin();
            }
        }
        System.out.println("Ziel!");
    }
}

