    public static void main(String[] args) {
        // Fahre, solange vorne frei ist: while (robot.frontIsClear())
    }
}

missions.solution:
public class HinUndZurueck {
    public static void main(String[] args) {
        while (robot.frontIsClear()) {
            robot.move();
            if (robot.onCoin()) {
                robot.pickCoin();
            }
        }
        robot.turnRight();
        robot.move();
        robot.turnRight();
        while (robot.frontIsClear()) {
            robot.move();
            if (robot.onCoin()) {
                robot.pickCoin();
            }
        }
    }
}

