    public static void main(String[] args) {
    }
}

missions.solution:
public class Huerdenlauf {
    static void springe() {
        robot.turnLeft();
        robot.move();
        robot.turnRight();
        robot.move();
        robot.move();
        robot.turnRight();
        robot.move();
        robot.turnLeft();
    }

    public static void main(String[] args) {
        while (!robot.atGoal()) {
            if (robot.frontIsClear()) {
                robot.move();
                if (robot.onCoin()) {
                    robot.pickCoin();
                }
            } else {
                springe();
            }
        }
    }
}

missions.starterCode:
public class Labyrinth {
    public static void main(String[] args) {
        while (!robot.atGoal()) {
            // Rechte Hand an der Wand ...
        }
    }
}

missions.solution:
public class Labyrinth {
    static void schritt() {
        if (robot.rightIsClear()) {
            robot.turnRight();
            robot.move();
        } else if (robot.frontIsClear()) {
            robot.move();
        } else {
            robot.turnLeft();
        }
    }

    public static void main(String[] args) {
        while (!robot.atGoal()) {
            schritt();
            if (robot.onCoin()) {
                robot.pickCoin();
            }
        }
    }
}

