        // Für jede Strecke: fahre(...) aufrufen, dann links drehen
    }
}

missions.solution:
public class Lageplan {
    static void fahre(int felder) {
        for (int i = 0; i < felder; i++) {
            robot.move();
            if (robot.onCoin()) {
                robot.pickCoin();
            }
        }
    }

    public static void main(String[] args) {
        int[] strecken = {4, 3, 2};
        for (int strecke : strecken) {
            fahre(strecke);
            robot.turnLeft();
        }
    }
}

