public class CodeKnacker {
    public static void main(String[] args) {
        String muster = "";
        // Fahre bis zum Ziel und hänge für jedes Feld "x" oder "." an
    }
}

missions.solution:
public class CodeKnacker {
    public static void main(String[] args) {
        String muster = "";
        while (!robot.atGoal()) {
            robot.move();
            if (robot.onCoin()) {
                robot.pickCoin();
                muster += "x";
            } else {
                muster += ".";
            }
        }
        System.out.println(muster);
    }
}
